def effective(cfg, tool, now):
    return [m.model for m in ModelRouter(cfg)._get_effective_models(tool, now=now)]


class FailingFirstClient:
    """第一个模型总是失败，第二个成功；记录每个模型被调用的次数。"""

    def __init__(self, fail_model):
        self.calls = []
        self.fail_model = fail_model

        class Completions:
            def create(_, model, messages, temperature, max_tokens, timeout):
                self.calls.append(model)
                if model == self.fail_model:
                    raise RuntimeError("simulated failure")
                return SimpleNamespace(
                    choices=[SimpleNamespace(message=SimpleNamespace(content=f"OK::{model}"))]
                )

        self.chat = SimpleNamespace(completions=Completions())


def test_max_retries_zero_tries_each_model_once():
    """max_retries_per_model=0 必须 fail-fast：单模型只试 1 次就降级。

    回归防护：值 0 不能被当成「未设置」而回退到默认重试次数。
    依据 router.py:216 的 range(max_retries_per_model + 1)。
    """
    client = FailingFirstClient(fail_model=FLASH)
    cfg = reader_cfg(scheduling())
    cfg.gateway.max_retries_per_model = 0
    res = ModelRouter(cfg, client=client).run_tool(
        "file_reader", [{"role": "user", "content": "hi"}], now=OFF
    )
    assert res.ok and res.model_used == GLM, (res.model_used, client.calls)
    # FLASH 只应被调用 1 次（无同模型重试），随后直接切到 GLM。
    assert client.calls == [FLASH, GLM], client.calls


def test_max_retries_one_tries_same_model_twice():
    """对照组：max_retries_per_model=1 时单模型试 2 次，证明 0 确实是 fail-fast。"""
    client = FailingFirstClient(fail_model=FLASH)
    cfg = reader_cfg(scheduling())
    cfg.gateway.max_retries_per_model = 1
    res = ModelRouter(cfg, client=client).run_tool(
        "file_reader", [{"role": "user", "content": "hi"}], now=OFF
    )
    assert res.ok and res.model_used == GLM, (res.model_used, client.calls)
    assert client.calls == [FLASH, FLASH, GLM], client.calls
